export const getRevokeApiKeyUrl = (keyId: string,) => {




  return `/api/settings/api-keys/${keyId}`
}

/**
 * @summary Revoke API key
 */
export const revokeApiKey = async (keyId: string, options?: Parameters<typeof customFetch>[1]): Promise<void> => {

  return customFetch<void>(getRevokeApiKeyUrl(keyId),
  {
    ...options,
    method: 'DELETE'


  }
);}





